-- Web Push for stride2ride.
--
-- Secrets live in Supabase Vault, never in the repo or in chat:
--   ride_notify_secret  shared header secret between the trip trigger and the
--                       ride-notify edge function, generated here in Postgres
--   ride_vapid_public / ride_vapid_private
--                       the VAPID pair, generated by ride-notify on its first
--                       call ({"kind":"init"}) and stored through ride.store_vapid
-- If VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY are set as edge function secrets,
-- the function prefers them.

create extension if not exists pg_net;

create table ride.push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  rider         text not null check (rider in ('adir', 'or', 'adi')),
  endpoint      text not null unique,
  p256dh        text not null,
  auth          text not null,
  device_label  text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index push_subscriptions_rider on ride.push_subscriptions (rider);
create trigger push_subscriptions_touch before update on ride.push_subscriptions
  for each row execute function ride.touch_updated_at();

-- RLS on, zero policies: only the service role (the app's server and the
-- edge function) reaches this table.
alter table ride.push_subscriptions enable row level security;
grant all on ride.push_subscriptions to service_role;

-- The shared secret, created once, never printed.
select vault.create_secret(
  replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  'ride_notify_secret',
  'stride2ride: x-ride-secret header between the trips trigger and the ride-notify edge function'
)
where not exists (select 1 from vault.secrets where name = 'ride_notify_secret');

-- What the edge function needs from Vault. service_role only.
create or replace function ride.notify_secrets() returns jsonb
language sql security definer set search_path = '' stable as $$
  select jsonb_build_object(
    'secret',        (select decrypted_secret from vault.decrypted_secrets where name = 'ride_notify_secret'),
    'vapid_public',  (select decrypted_secret from vault.decrypted_secrets where name = 'ride_vapid_public'),
    'vapid_private', (select decrypted_secret from vault.decrypted_secrets where name = 'ride_vapid_private')
  )
$$;

-- Store the VAPID pair once. A second call is ignored: rotating keys would
-- silently invalidate every phone's subscription.
create or replace function ride.store_vapid(p_public text, p_private text) returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from vault.secrets where name = 'ride_vapid_public') then
    return false;
  end if;
  perform vault.create_secret(p_public, 'ride_vapid_public', 'stride2ride: VAPID public key');
  perform vault.create_secret(p_private, 'ride_vapid_private', 'stride2ride: VAPID private key');
  return true;
end $$;

-- The public key is public: the app hands it to the browser to subscribe.
create or replace function ride.vapid_public_key() returns text
language sql security definer set search_path = '' stable as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'ride_vapid_public'
$$;

-- POST a payload to ride-notify with the shared secret. Async (pg_net):
-- returns the request id, never waits, never raises.
create or replace function ride.call_notify(payload jsonb) returns bigint
language plpgsql security definer set search_path = '' as $$
declare
  s text;
  req bigint;
begin
  select decrypted_secret into s from vault.decrypted_secrets where name = 'ride_notify_secret';
  if s is null then
    return null;
  end if;
  select net.http_post(
    url := 'https://xmjxfnmqsvxxevhxxalq.supabase.co/functions/v1/ride-notify',
    body := payload,
    headers := jsonb_build_object('content-type', 'application/json', 'x-ride-secret', s),
    timeout_milliseconds := 10000
  ) into req;
  return req;
exception when others then
  return null;
end $$;

-- Left: a new open trip. Returned: ended_at goes from null to a time.
-- A trip added by hand that is already finished notifies nobody.
-- Logging a trip must never fail because of a notification.
create or replace function ride.notify_trip() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  k text;
begin
  if tg_op = 'INSERT' and new.started_at is not null and new.ended_at is null then
    k := 'left';
  elsif tg_op = 'UPDATE' and old.ended_at is null and new.ended_at is not null then
    k := 'returned';
  else
    return null;
  end if;
  perform ride.call_notify(jsonb_build_object(
    'kind', k, 'rider', new.rider, 'car', new.car, 'trip_id', new.id
  ));
  return null;
exception when others then
  return null;
end $$;

create trigger trips_notify after insert or update of ended_at on ride.trips
  for each row execute function ride.notify_trip();

-- The settings page's test button: only to the device that asked.
create or replace function ride.send_test_push(p_endpoint text) returns bigint
language sql security definer set search_path = '' as $$
  select ride.call_notify(jsonb_build_object('kind', 'test', 'endpoint', p_endpoint))
$$;

revoke execute on function ride.notify_secrets(), ride.store_vapid(text, text), ride.vapid_public_key(),
  ride.call_notify(jsonb), ride.notify_trip(), ride.send_test_push(text) from public, anon, authenticated;
grant execute on function ride.notify_secrets(), ride.store_vapid(text, text), ride.vapid_public_key(),
  ride.call_notify(jsonb), ride.send_test_push(text) to service_role;
